pub fn get_trino_root_grammar_id() -> GrammarId {
    GrammarId(1244)
}
pub fn get_trino_root_grammar_table() -> RootGrammar {
    RootGrammar {
        grammar_id: get_trino_root_grammar_id(),
        tables: &TRINO_TABLES,
    }
}
pub fn get_trino_root_grammar() -> RootGrammar {
    get_trino_root_grammar_table()
}
